mapper.select:
select ri.id, ri.room_number, ri.rent, ai.id apartment_id, ai.name apartment_name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release from room_info ri left join apartment_info ai on ri.apartment_id = ai.id and ai.is_deleted = 0 where ri.is_deleted = 0 and ri.is_release = 1
and ai.province_id = #{queryVo.provinceId}
and ai.city_id = #{queryVo.cityId}
and ai.district_id = #{queryVo.districtId}
and ri.rent >= #{queryVo.minRent}
and ri.rent <= #{queryVo.maxRent}
and ri.id in ( select room_id from room_payment_type where payment_type_id = #{queryVo.paymentTypeId} and is_deleted = 0 )
and ( ri.room_number like concat('%', #{queryVo.keyword}, '%') or ai.name like concat('%', #{queryVo.keyword}, '%') or ai.address_detail like concat('%', #{queryVo.keyword}, '%') )
order by ri.rent asc
order by ri.rent desc
